-- Aluna supplied 2025 urban-area dataset; population values remain attributed to the source workbook.
alter table public.places add column source_key text unique;
alter table public.places add column region text;
alter table public.places add column population bigint check (population is null or population >= 0);
alter table public.places add column latitude double precision check (latitude between -90 and 90);
alter table public.places add column longitude double precision check (longitude between -180 and 180);
alter table public.places add column population_source text;
on conflict (source_key) do update set name=excluded.name, country_code=excluded.country_code, region=excluded.region, population=excluded.population, latitude=excluded.latitude, longitude=excluded.longitude, population_source=excluded.population_source;
